            self.v.validate("UPPERCASE1!")

    def test_missing_digit_rejected(self):
        with self.assertRaises(ValidationError):
            self.v.validate("NoDigitsHere!")

    def test_missing_special_char_rejected(self):
        with self.assertRaises(ValidationError):
            self.v.validate("NoSpecial123")

    def test_valid_password_passes(self):
        self.v.validate("Valid1Pass!")  # must not raise

    def test_get_help_text_returns_string(self):
        self.assertIsInstance(self.v.get_help_text(), str)
