from django.contrib.auth import get_user_model
from rest_framework import status
from rest_framework.test import APITestCase

User = get_user_model()

class ChangePasswordValidatorChainTests(APITestCase):
    def setUp(self):
        self.user = User.objects.create_user(
            username="pwuser", email="pw@example.com", password="OldPass1!",
        )
        self.client.force_authenticate(user=self.user)
        self.url = "/api/auth/change-password/"  # or reverse("change_password")

    def _change(self, new_password):
        return self.client.post(self.url, {
            "old_password": "OldPass1!",
            "new_password": new_password,
            "confirm_password": new_password,
        }, format="json")

    def test_all_numeric_password_rejected(self):
        resp = self._change("12345678901234!")  # numeric + still fails complexity/common
        self.assertEqual(resp.status_code, status.HTTP_400_BAD_REQUEST)

    def test_common_password_rejected(self):
        resp = self._change("Password1!")  # common word list hit despite passing complexity
        self.assertEqual(resp.status_code, status.HTTP_400_BAD_REQUEST)

    def test_similar_to_username_or_email_rejected(self):
        resp = self._change("Pwuser123!")
        self.assertEqual(resp.status_code, status.HTTP_400_BAD_REQUEST)

    def test_compliant_password_accepted(self):
        resp = self._change("Br@ndNewPass9")
        self.assertEqual(resp.status_code, status.HTTP_200_OK)
