from django.test import SimpleTestCase
from mcp_connector.views import _classify_sync_error, MCP_ERR_HOST_TOOL, MCP_ERR_PROTOCOL, MCP_ERR_OOM

class ClassifySyncErrorTests(SimpleTestCase):
    def test_host_tool_install_failure_classified(self):
        code, _ = _classify_sync_error("host tool install failed: pip:semgrep")
        self.assertEqual(code, MCP_ERR_HOST_TOOL)

    def test_protocol_handshake_failure_classified(self):
        code, _ = _classify_sync_error("mcp_protocol_handshake_failed: no response")
        self.assertEqual(code, MCP_ERR_PROTOCOL)

    def test_oom_checked_before_generic_exit_code(self):
        # message contains BOTH "exited with code 137" and OOM fingerprints;
        # OOM branch must win per the documented ordering guarantee
        code, _ = _classify_sync_error("process exited with code 137 (oom-killed)")
        self.assertEqual(code, MCP_ERR_OOM)
