from unittest.mock import patch
from rest_framework.test import APITestCase
from rest_framework import status

class PolicyTestViewTOCTOUTests(APITestCase):
    def test_policy_disabled_between_validation_and_eval_still_applies_it(self):
        """Repro: policy_row fetched enabled=True, then policies_qs re-fetched
        without the enabled filter -- a policy disabled in that window still
        gets evaluated against."""
        policy = self.make_policy(enabled=True)
        self.client.force_authenticate(user=self.make_user(org=policy.organization))
        original_filter = type(policy).objects.filter
        calls = {"n": 0}

        def flip_after_first(*args, **kwargs):
            calls["n"] += 1
            if calls["n"] == 2:
                policy.enabled = False
                policy.save(update_fields=["enabled"])
            return original_filter(*args, **kwargs)

        with patch("policy.models.Policy.objects.filter", side_effect=flip_after_first):
            resp = self.client.post("/api/policies/test/", {
                "policy_id": policy.id, "prompt": "test prompt",
            }, format="json")
        # documents current (buggy) behavior pending the fix; once fixed this
        # should assert the disabled policy is NOT applied instead
        self.assertEqual(resp.status_code, status.HTTP_200_OK)

    def test_cross_org_policy_id_returns_404_not_leaked(self):
        other_org_policy = self.make_policy(org=self.make_org("other-org"))
        self.client.force_authenticate(user=self.make_user(org=self.make_org("mine")))
        resp = self.client.post("/api/policies/test/", {
            "policy_id": other_org_policy.id, "prompt": "hi",
        }, format="json")
        self.assertEqual(resp.status_code, status.HTTP_404_NOT_FOUND)
